import io

def summarize_expenses(csv_text):
    """Total the amount column per category.

    Returns {category: total} with each total rounded to 2 decimals.
    Category keys are lowercase with surrounding whitespace stripped.
    Amounts may be quoted and may use $ and thousands separators.
    An amount wrapped in parentheses is negative, accounting style.
    Rows with a missing or empty amount are skipped, as are blank lines.
    """
    totals = {}
    reader = csv.reader(io.StringIO(csv_text.strip()))

    try:
        next(reader) # skip header
    except StopIteration:
        return {}

    for row in reader:
        if not row:
            continue
        if len(row) < 3:
            continue

        cat_raw = row[1]
        amount_raw = row[2]

        if not amount_raw or not amount_raw.strip():
            continue

        category = cat_raw.strip().lower()
        amount_str = amount_raw.strip()

        is_negative = False
        if amount_str.startswith('(') and amount_str.endswith(')'):
            is_negative = True
            amount_str = amount_str[1:-1]
        elif amount_str.startswith('-'):
            is_negative = True
            amount_str = amount_str[1:]

        amount_str = amount_str.replace('$', '').replace(',', '')

        try:
            amount = float(amount_str)
            if is_negative:
                amount = -amount
            totals[category] = totals.get(category, 0) + amount
        except ValueError:
            continue

    return {cat: round(val, 2) for cat, val in totals.items()}
